/**
 * ============================================================================
 * DATA RUANGAN DAN GEDUNG UNIVERSITAS NEGERI MEDAN (UNIMED)
 * Sumber Data:
 * - FMIPA.js (12 Gedung FMIPA)
 * - Ruangan Unimed.xlsx (FT, FIKK, FBS, FIS, FEB, FIP)
 * ============================================================================
 * Ringkasan Dataset Kampus:
 * - Total Fakultas : 7 Fakultas (FMIPA, FT, FIKK, FBS, FIS, FEB, FIP)
 * - Total Gedung   : 30 Gedung
 * - Total Ruangan  : 1.337 Ruangan / Fasilitas
 *
 * Rincian Total Ruangan per Fakultas:
 * - FMIPA : 672 Ruangan (12 Gedung: 001 - 012)
 * - FEB   : 132 Ruangan (2 Gedung: 035, 036)
 * - FIP   : 126 Ruangan (4 Gedung: 037, 038, 039, 190)
 * - FBS   : 124 Ruangan (3 Gedung: 020, 021, 022)
 * - FIKK  : 112 Ruangan (3 Gedung: 031, 032, 033)
 * - FIS   : 97 Ruangan  (3 Gedung: 026, 027, 028)
 * - FT    : 74 Ruangan  (3 Gedung: 017, 076, 077)
 *
 * Struktur Data Objek Ruangan:
 * @typedef {Object} Ruangan
 * @property {number} id - ID unik sekuensial (1 - 1337)
 * @property {string} fakultas - Singkatan Fakultas (FMIPA, FT, FIKK, FBS, FIS, FEB, FIP)
 * @property {string} kodeGedung - Kode gedung 3 digit (contoh: '001', '017', '190')
 * @property {string} namaGedung - Nama lengkap gedung
 * @property {number} lantai - Lantai keberadaan ruangan (integer: 1, 2, 3, dst.)
 * @property {number|string|null} ruangan - Nomor ruangan (angka/string untuk sub-ruang, null untuk area umum)
 * @property {string} kodeRuangan - Kode baku ruangan (contoh: '001.1.01', '026.1', '031.1.05.1')
 * @property {string} namaRuangan - Nama/kegunaan ruangan
 * @property {Object|Array|null} koordinat - Nilai koordinat geo-spasial (default: null)
 *
 * Integrasi Peta Web (Leaflet / Mapbox / OpenLayers) & Routing (Dijkstra / A*):
 * - Key penghubung layer GeoJSON: `kodeGedung` (relasi gedung) & `kodeRuangan` (relasi node ruangan).
 * - Multi-level floor routing menggunakan properti `lantai`.
 * ============================================================================
 */


