/**
 * Cari ruangan berdasarkan query pencarian (nama ruangan, kode ruangan, nama gedung, atau fakultas)
 * @param {string} keyword - Kata kunci pencarian
 * @returns {Array<Object>} Daftar ruangan yang cocok
 */
export function cariRuanganByQuery(keyword) {
  if (!keyword || typeof keyword !== 'string') return [];
  const q = keyword.toLowerCase().trim();
  if (!q) return [];
  return dataRuangan.filter(r =>
    (r.namaRuangan && r.namaRuangan.toLowerCase().includes(q)) ||
    (r.kodeRuangan && r.kodeRuangan.toLowerCase().includes(q)) ||
    (r.namaGedung && r.namaGedung.toLowerCase().includes(q)) ||
    (r.fakultas && r.fakultas.toLowerCase().includes(q))
  );
}

/**
 * Alias fungsi cariRuangan untuk kompatibilitas penuh dengan sistem eksisting FMIPA.js
 * @param {string} keyword - Kata kunci pencarian
 * @returns {Array<Object>}
 */
export function cariRuangan(keyword) {
  return cariRuanganByQuery(keyword);
}

/**
 * Filter ruangan berdasarkan fakultas
 * @param {string} fakultas - Kode fakultas ('FMIPA', 'FT', 'FIKK', 'FBS', 'FIS', 'FEB', 'FIP') atau nama fakultas
 * @returns {Array<Object>} Daftar ruangan pada fakultas tersebut
 */
export function filterByFakultas(fakultas) {
  if (!fakultas || typeof fakultas !== 'string') return [];
  const target = fakultas.toLowerCase().trim();
  return dataRuangan.filter(r => {
    if (!r.fakultas) return false;
    const fakCode = r.fakultas.toLowerCase();
    const fullName = (daftarFakultas[r.fakultas] || '').toLowerCase();
    return fakCode === target || fullName.includes(target);
  });
}

/**
 * Filter ruangan berdasarkan gedung dan lantai
 * @param {string} gedung - Kode gedung (misal: '001', '017') atau nama gedung
 * @param {number|string} lantai - Nomor lantai
 * @returns {Array<Object>} Daftar ruangan pada gedung dan lantai tersebut
 */
export function filterByGedungDanLantai(gedung, lantai) {
  if (!gedung) return [];
  const gTarget = String(gedung).toLowerCase().trim();
  const ltNum = Number(lantai);
  return dataRuangan.filter(r => {
    const matchGedung = (
      r.kodeGedung.toLowerCase() === gTarget ||
      r.namaGedung.toLowerCase().includes(gTarget)
    );
    const matchLantai = isNaN(ltNum) ? true : r.lantai === ltNum;
    return matchGedung && matchLantai;
  });
}

/**
 * Ambil daftar ruangan berdasarkan kode gedung
 * @param {string} kodeGedung - Kode gedung (misal: '001', '017', dst.)
 * @returns {Array<Object>} Daftar ruangan milik gedung tersebut
 */
export function getRuanganByGedung(kodeGedung) {
  if (!kodeGedung) return [];
  const kode = String(kodeGedung).toLowerCase().trim();
  return dataRuangan.filter(r =>
    r.kodeGedung.toLowerCase() === kode ||
    r.namaGedung.toLowerCase() === kode
  );
}

/**
 * Ambil daftar ruangan berdasarkan kode gedung dan lantai (kompatibilitas FMIPA.js)
 * @param {string} kodeGedung - Kode gedung
 * @param {number|string} lantai - Nomor lantai
 * @returns {Array<Object>}
 */
export function getRuanganByLantai(kodeGedung, lantai) {
  return filterByGedungDanLantai(kodeGedung, lantai);
}

/**
 * Ambil metadata satu gedung berdasarkan kode gedung
 * @param {string} kodeGedung - Kode gedung
 * @returns {Object|null} Informasi gedung
 */
export function getGedungByKode(kodeGedung) {
  if (!kodeGedung) return null;
  const kode = String(kodeGedung).toLowerCase().trim();
  return daftarGedung.find(g =>
    g.kodeGedung.toLowerCase() === kode ||
    g.namaGedung.toLowerCase() === kode ||
    g.namaSingkat.toLowerCase() === kode
  ) || null;
}

/**
 * Ambil daftar gedung berdasarkan fakultas
 * @param {string} fakultas - Kode atau nama fakultas
 * @returns {Array<Object>}
 */
export function getGedungByFakultas(fakultas) {
  if (!fakultas || typeof fakultas !== 'string') return [];
  const target = fakultas.toLowerCase().trim();
  return daftarGedung.filter(g => {
    const fakCode = g.fakultas.toLowerCase();
    const fullName = (daftarFakultas[g.fakultas] || '').toLowerCase();
    return fakCode === target || fullName.includes(target);
  });
}

/**
 * Ambil ringkasan statistik dataset
 * @returns {Object}
 */
export function getStatistik() {
  const perFakultas = {};
  for (const [code, name] of Object.entries(daftarFakultas)) {
    const rooms = dataRuangan.filter(r => r.fakultas === code);
    const buildings = daftarGedung.filter(g => g.fakultas === code);
    perFakultas[code] = {
      namaFakultas: name,
      totalGedung: buildings.length,
      totalRuangan: rooms.length,
      gedung: buildings.map(b => b.kodeGedung)
    };
  }
  return {
    totalRuangan: dataRuangan.length,
    totalGedung: daftarGedung.length,
    totalFakultas: Object.keys(daftarFakultas).length,
    perFakultas
  };
}

// Browser Window Global Compatibility
if (typeof window !== 'undefined') {
  window.daftarFakultas = daftarFakultas;
  window.daftarGedung = daftarGedung;
  window.dataRuangan = dataRuangan;
  window.dataGedung = dataGedung;
  window.cariRuanganByQuery = cariRuanganByQuery;
  window.cariRuangan = cariRuangan;
  window.filterByFakultas = filterByFakultas;
  window.filterByGedungDanLantai = filterByGedungDanLantai;
  window.getRuanganByGedung = getRuanganByGedung;
  window.getRuanganByLantai = getRuanganByLantai;
  window.getGedungByKode = getGedungByKode;
  window.getGedungByFakultas = getGedungByFakultas;
  window.getStatistik = getStatistik;
}

// CommonJS compatibility (Node.js)
if (typeof module !== 'undefined' && typeof module.exports !== 'undefined') {
  module.exports = {
    daftarFakultas,
    daftarGedung,
    dataRuangan,
    dataGedung,
    cariRuanganByQuery,
    cariRuangan,
    filterByFakultas,
    filterByGedungDanLantai,
    getRuanganByGedung,
    getRuanganByLantai,
    getGedungByKode,
    getGedungByFakultas,
    getStatistik,
    default: dataRuangan
  };
}

// Default export untuk ES Module
export default dataRuangan;
